"""Package completed desktop coexistence evidence beside the reviewed quality study."""
from pathlib import Path
import argparse, hashlib, json, shutil, statistics
from summarize_cuni_benchmark import summarize


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--benchmark',type=Path,required=True)
    p.add_argument('--quality',type=Path,required=True)
    p.add_argument('--controller',type=Path,required=True)
    p.add_argument('--output',type=Path,required=True)
    a=p.parse_args()
    assert (a.benchmark/'DESKTOP-COMPLETE.json').exists()
    a.output.mkdir(parents=True,exist_ok=True)
    raw=a.output/'data';raw.mkdir(exist_ok=True)
    results={name:summarize(a.benchmark/name) for name in ['cuni-q3km','cuni-q8']}
    quality=json.loads((a.quality/'data/comparison.json').read_text(encoding='utf-8'))
    for name,key in [('cuni-q3km','q3'),('cuni-q8','q8')]:
        source=a.benchmark/name
        actual={r['id']:r['translation'].strip() for r in map(json.loads,(source/'quality-300-results.jsonl').read_text(encoding='utf-8').splitlines())}
        assert all(actual[r['id']]==r[key].strip() for r in quality), 'Changed translations need a new quality review'
        dest=raw/name;dest.mkdir(exist_ok=True)
        for f in source.iterdir():
            if f.is_file() and (f.suffix in {'.json','.jsonl','.csv'} or f.name=='Modelfile'):
                shutil.copy2(f,dest/f.name)
        row=results[name]
        phases=[row['phases'][f'paced-{i}'] for i in range(1,4)]
        def weighted(key):
            values=[phase['gpu'][key] for phase in phases]
            return sum(s['mean']*s['n'] for s in values)/sum(s['n'] for s in values)
        row['paced_gpu_mean_percent']=weighted('utilization.gpu')
        row['paced_power_mean_w']=weighted('power.draw')
        row['paced_used_mean_mib']=weighted('memory.used')
        row['active_mean_fps']=statistics.mean(r['active_fps'] for r in row['paired_cycles'])
        row['control_mean_fps']=statistics.mean(r['control_fps'] for r in row['paired_cycles'])
        row['fps_change_mean_percent']=statistics.mean(r['change_percent'] for r in row['paired_cycles'])
    for filename in ['baseline-provenance.json','hardware.json','processes.json','runtime-version.json','app-log.json','DESKTOP-COMPLETE.json','cuni-q3km-model-info.json','cuni-q8-model-info.json','evaluate_cuni.py','sample_nvml.py']:
        shutil.copy2(a.benchmark/filename,raw/filename)
    for filename in ['summarize_cuni_benchmark.py','build_cuni_desktop_report.py']:
        shutil.copy2(Path(__file__).parent/filename,raw/filename)
    shutil.copy2(a.controller,raw/'run_desktop_benchmark.py')
    shutil.copytree(a.quality,a.output/'quality',dirs_exist_ok=True)
    (raw/'summary.json').write_text(json.dumps(results,indent=2),encoding='utf-8')
    (raw/'quality-identity-check.json').write_text(json.dumps({'cases_per_model':300,'comparison':'strip surrounding whitespace only','q3_matches_reviewed_preflight':True,'q8_matches_reviewed_preflight':True},indent=2),encoding='utf-8')
    payload=json.dumps(results,ensure_ascii=False).replace('</','<\\/')
    (a.output/'index.html').write_text(TEMPLATE.replace('__DATA__',payload),encoding='utf-8')
    (a.output/'README.txt').write_text('Open index.html for desktop coexistence results, quality/report.html for all 300 reviewed pairs.\nAll quality outputs from the concurrent runs match the separately reviewed preflight after stripping surrounding whitespace.\nExact-text inference ran beside preview.12 CPU OCR, VFG 2x Medium and experimental NR 65% / 720p on a 1080p30 sample loop. It did not replace the CPU worker during this controlled benchmark.\nSeparate native integration tests validate the new preview.13 OCR/CUNI pipeline.\nWhole-device NVML includes other desktop processes. Application content submissions are not measured physical monitor FPS. Translation timings exclude OCR/stabilization.\nData includes original environment paths and reproduction scripts: adapt the paths before rerunning. No weights, executables or private NR DLLs.\n',encoding='utf-8')
    files=[dict(file=f.relative_to(a.output).as_posix(),bytes=f.stat().st_size,sha256=hashlib.sha256(f.read_bytes()).hexdigest()) for f in sorted(a.output.rglob('*')) if f.is_file() and f.name!='files-sha256.json']
    (a.output/'files-sha256.json').write_text(json.dumps(files,indent=2),encoding='utf-8')
    print(json.dumps({k:{x:v[x] for x in ['active_mean_fps','control_mean_fps','fps_change_mean_percent','paced_gpu_mean_percent','paced_power_mean_w','resident_extra_mib','minimum_free_mib']} for k,v in results.items()},indent=2))


TEMPLATE=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FrameLab · CUNI Q3 / Q8 desktop results</title>
<style>:root{color-scheme:dark;--bg:#101511;--panel:#1a2119;--ink:#eef0e7;--muted:#a7afa0;--line:#394331;--lime:#c1ff5e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.65 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:28px 24px 72px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:20px}a{color:var(--lime)}header a{font-weight:800;text-decoration:none;font-size:24px}button{font:inherit;color:inherit;background:var(--panel);border:1px solid var(--line);padding:9px 15px;cursor:pointer;border-radius:5px}a:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid var(--lime);outline-offset:4px}h1{font-size:clamp(36px,6vw,64px);line-height:1.08;letter-spacing:-2px;max-width:900px;margin:40px 0 24px}h2{font-size:26px;line-height:1.2;margin-top:40px}p{max-width:85ch}.meta{color:var(--muted);font-size:14px}.notice{border-left:3px solid #ff8659;padding:12px 18px;background:#231e16}.cards{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:30px 0}.card{background:var(--panel);padding:24px;border:1px solid var(--line);border-radius:8px}.card h2{margin:0 0 14px;font-size:22px}.big{font-size:48px;line-height:1.2;font-weight:750;color:var(--lime)}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:500px;font-variant-numeric:tabular-nums}td,th{padding:12px 14px;border-bottom:1px solid var(--line);text-align:left}thead th{color:var(--muted);font-size:14px}th:first-child{width:48%}.links{display:flex;gap:20px;flex-wrap:wrap}details{border:1px solid var(--line);border-radius:6px;padding:16px;margin:16px 0}summary{cursor:pointer}footer{margin-top:40px;border-top:1px solid var(--line);padding-top:24px}@media(max-width:650px){main{padding:20px 16px}.cards{grid-template-columns:1fr}h1{letter-spacing:-1px}.big{font-size:40px}}</style>
<main><header><a href="https://opicebot.cz/framelab/">FRAME / LAB</a><button id="lang" type="button">Čeština</button></header><p class="meta">RTX 5070 Ti · CUNI-MH 7B · 2026-11-19</p><h1 id="title"></h1><p id="intro"></p><p class="notice" id="scope"></p><div class="cards" id="cards"></div><h2 id="resultTitle"></h2><div class="scroll"><table><thead><tr><th id="metric"></th><th>Q3_K_M</th><th>Q8_0</th></tr></thead><tbody id="metrics"></tbody></table></div><p class="meta" id="units"></p><h2 id="qualityTitle"></h2><p id="qualityText"></p><p class="links"><a id="qualityLink" href="quality/report.html"></a><a href="quality/data/comparison.csv">CSV · 300</a><a href="data/summary.json">JSON · performance</a></p><h2 id="methodTitle"></h2><p id="method"></p><p id="protocol"></p><p id="limits"></p><div id="cycles"></div><p class="links"><a href="data/hardware.json">Hardware</a><a href="data/processes.json">App settings</a><a href="data/cuni-q3km/manifest.json">Q3 prompt / settings</a><a href="data/cuni-q8/manifest.json">Q8 prompt / settings</a><a href="data/evaluate_cuni.py">Evaluator</a><a href="files-sha256.json">SHA-256 / all files</a></p><footer><p id="rights"></p><a href="https://opicebot.cz/framelab/guide/subtitles-en.html" id="guide"></a> · <a href="https://github.com/tomik520i/FrameLab">GitHub</a></footer></main><script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),keys=['cuni-q3km','cuni-q8'],$=id=>document.getElementById(id);let cs=new URLSearchParams(location.search).get('lang')==='cs';const t=(en,cz)=>cs?cz:en,fmt=(n,d=1)=>Number(n).toLocaleString(cs?'cs-CZ':'en-US',{maximumFractionDigits:d,minimumFractionDigits:d});function el(tag,text){const n=document.createElement(tag);n.textContent=text;return n}
function render(){document.documentElement.lang=cs?'cs':'en';$('lang').textContent=t('Čeština','English');$('title').textContent=t('Q3 or Q8 while frame gen is running?','Q3, nebo Q8 při běžícím frame genu?');const q3=data[keys[0]],q8=data[keys[1]],saved=100*(1-q3.paced_latency_ms.median/q8.paced_latency_ms.median);$('intro').textContent=t(`On this desktop, Q3 translation took ${fmt(saved)}% less time at the median. The same 300 sentences showed no clear quality advantage for Q8. Start with Q3; Q8 remains an optional comparison.`,`Na tomto PC zabral překlad Q3 v mediánu o ${fmt(saved)} % méně času. Stejných 300 vět neukázalo jasnou kvalitativní výhodu Q8. Začněte Q3; Q8 zůstává volitelnou alternativou pro porovnání.`);$('scope').textContent=t('Exact-text inference alongside running VFG, NR and CPU OCR. These are model request times and software output counters, not full subtitle delay or physically measured monitor FPS.','Překlad přesného textu při současně běžícím VFG, NR a CPU OCR. Jde o dobu požadavku modelu a softwarové čítače výstupu, nikoli celé zpoždění titulků nebo fyzicky změřené FPS monitoru.');$('cards').replaceChildren();for(const [i,k] of keys.entries()){const card=el('article','');card.className='card';const n=el('div',fmt(data[k].paced_latency_ms.median,0)+' ms');n.className='big';card.append(el('h2',i?'CUNI-MH Q8_0':'CUNI-MH Q3_K_M'),n,el('p',t('Median translation · 180 paced requests','Medián překladu · 180 periodických požadavků')));$('cards').append(card)}$('resultTitle').textContent=t('Measured alongside processing','Naměřeno při zpracování obrazu');$('metric').textContent=t('Metric','Metrika');$('metrics').replaceChildren();const metrics=[[t('Translation p95','Překlad p95'),r=>fmt(r.paced_latency_ms.p95,0)+' ms'],[t('Requests above 2 seconds','Požadavky nad 2 sekundy'),r=>r.paced_over_2s+' / 180'],[t('Output during paced translation','Výstup při periodickém překladu'),r=>fmt(r.active_mean_fps)+' fps'],[t('Adjacent unloaded controls','Sousední kontroly bez GPU modelu'),r=>fmt(r.control_mean_fps)+' fps'],[t('Output change vs own controls','Změna výstupu proti vlastním kontrolám'),r=>fmt(r.fps_change_mean_percent)+' %'],[t('Whole-GPU utilization, paced mean','Vytížení celé GPU, periodický průměr'),r=>fmt(r.paced_gpu_mean_percent)+' %'],[t('Whole-GPU power, paced mean','Příkon celé GPU, periodický průměr'),r=>fmt(r.paced_power_mean_w)+' W'],[t('Extra memory with model resident','Paměť navíc s načteným modelem'),r=>fmt(r.resident_extra_mib/1024,2)+' GiB'],[t('Minimum free memory across phases','Nejméně volné paměti napříč fázemi'),r=>fmt(r.minimum_free_mib/1024,2)+' GiB']];for(const [label,value] of metrics){const tr=el('tr','');tr.append(el('th',label),...keys.map(k=>el('td',value(data[k]))));$('metrics').append(tr)}$('units').textContent=t('NVML whole-device samples at 1 Hz. Phase summaries omit the first 5 and last 2 seconds; request latencies use every completed request. Memory uses binary GiB, excluding reserved memory.','NVML vzorkuje celou kartu 1× za sekundu. Souhrny fází vynechávají prvních 5 a poslední 2 sekundy; latence zahrnují všechny dokončené požadavky. Paměť v binárních GiB, bez rezervované paměti.');$('qualityTitle').textContent=t('300 sentences, both quantizations','300 vět, obě kvantizace');$('qualityText').textContent=t('271/300 acceptable for each model; major errors: Q3 2, Q8 5. Q8 scored higher in 17 cases and lower in 16. All concurrent outputs match the separately reviewed text-only preflight after trimming surrounding whitespace. Grades are assistant judgments, not a blinded independent human study.','Oba modely: 271/300 přijatelných; zásadní chyby: Q3 2, Q8 5. Q8 získal vyšší známku v 17 případech a nižší v 16. Všechny výstupy souběžného běhu odpovídají samostatně hodnocenému předběžnému testu po odstranění okolních mezer. Známky určil asistent, nejde o slepý nezávislý lidský test.');$('qualityLink').textContent=t('Inspect all 300 pairs →','Prohlédnout všech 300 párů →');$('qualityLink').href='quality/report.html'+(cs?'?lang=cs':'');$('methodTitle').textContent=t('Setup and method','Sestava a postup');$('method').textContent=t('Ryzen 9 5900X, 64 GB RAM, RTX 5070 Ti 16 GB, driver 617.14, Windows 11 Pro. Unmodified preview.12 played the same 1080p30 CS:GO loop with VFG 2× Medium, experimental NR 65% / 720p and the existing CPU OCR pipeline enabled. CUNI requests used a separate local Ollama 0.40.16 process with verified full GPU offload. The capture card was not used; no game was rendered on this GPU.','Ryzen 9 5900X, 64 GB RAM, RTX 5070 Ti 16 GB, ovladač 617.14, Windows 11 Pro. Neupravená preview.12 přehrávala stejnou 1080p30 smyčku CS:GO s VFG 2× Medium, experimentálním NR 65 % / 720p a zapnutou původní CPU OCR cestou. CUNI požadavky zpracoval samostatný lokální Ollama 0.40.16 s ověřeným plným načtením do GPU. Střihovka nebyla použita; na GPU se nerenderovala hra.');$('protocol').textContent=t('For each model: 60 s unloaded baseline, warmup, 30 s resident idle, 300 back-to-back translations, then three 60-request cycles spaced at least 2 s apart. Each cycle has its own 60 s unloaded controls before and after. The same fixed corpus and prompt were used for Q3 and Q8; references were never supplied to the model. Raw phases, individual requests and telemetry are linked below.','Pro každý model: 60 s kontrola bez modelu, zahřátí, 30 s načtený nečinný model, 300 překladů za sebou a tři cykly po 60 požadavcích s odstupem alespoň 2 s. Každý cyklus má vlastní 60s kontroly bez modelu před i po něm. Q3 a Q8 dostaly stejný korpus i prompt; reference model nikdy neviděl. Níže jsou surové fáze, požadavky a telemetrie.');$('limits').textContent=t('This controlled benchmark kept the baseline CPU OCR path active; it did not time the new integrated CUNI subtitle pipeline end to end. Separate real-image integration tests cover that path. Results depend on input resolution, frame-gen multiplier, enhancer settings, other GPU work and OCR readability. Higher quantization is not a guarantee of better translation.','Řízený benchmark nechal běžet původní CPU OCR cestu; neměřil celkové zpoždění nových integrovaných CUNI titulků. Tuto cestu ověřují samostatné testy se skutečným OCR z obrazu. Výsledek závisí na rozlišení, násobiči frame genu, enhanceru, další práci GPU a čitelnosti textu. Vyšší kvantizace nezaručuje lepší překlad.');$('cycles').replaceChildren();for(const [i,k] of keys.entries()){const d=el('details','');d.append(el('summary',(i?'Q8':'Q3')+t(' · individual cycles and raw evidence',' · jednotlivé cykly a surová data')));for(const c of data[k].paired_cycles)d.append(el('p',t('Cycle ','Cyklus ')+c.cycle+': '+fmt(c.control_fps)+' → '+fmt(c.active_fps)+' fps ('+fmt(c.change_percent)+' %)'));const links=el('p','');links.className='links';for(const [file,label] of [['phases.json','Phases'],['app-telemetry.csv','App CSV'],['quality-300-results.jsonl','300 requests'],['paced-1-gpu.jsonl','GPU 1'],['paced-2-gpu.jsonl','GPU 2'],['paced-3-gpu.jsonl','GPU 3']]){const a=el('a',label);a.href='data/'+k+'/'+file;links.append(a)}d.append(links);$('cycles').append(d)}$('rights').textContent=t('Game text, source licenses, model cards and attribution are retained in the quality report. No model weights or private NR libraries are included. Original notebook results remain separate.','Herní texty, licence zdrojů, modelové karty a autorství jsou zachovány v reportu kvality. Balík neobsahuje modelové váhy ani soukromé NR knihovny. Původní notebookové výsledky zůstávají oddělené.');$('guide').textContent=t('Subtitle setup guide','Návod k titulkům');$('guide').href='https://opicebot.cz/framelab/guide/'+(cs?'subtitles.html':'subtitles-en.html')}
$('lang').addEventListener('click',()=>{cs=!cs;render()});render();</script></html>'''


